-- Read-only catalog audit. No role switches, grants, DDL or application writes.
BEGIN READ ONLY;
SET LOCAL statement_timeout='15s';
WITH roles AS (SELECT oid,rolname FROM pg_roles WHERE rolname IN ('leqvor_governance_auditor','leqvor_governance_control','leqvor_governance_executor','neondb_owner'))
SELECT jsonb_build_object(
 'identity',jsonb_build_object('database',current_database(),'user',current_user,'server',current_setting('server_version'),'read_only',current_setting('transaction_read_only')),
 'role_flags',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'login',rolcanlogin,'super',rolsuper,'create_db',rolcreatedb,'create_role',rolcreaterole,'inherit',rolinherit,'replicate',rolreplication,'bypass_rls',rolbypassrls)) FROM pg_roles r JOIN roles x ON x.oid=r.oid),
 'memberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('member',a.rolname,'role',b.rolname,'admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option,'grantor',g.rolname)),'[]') FROM pg_auth_members m JOIN pg_roles a ON a.oid=m.member JOIN pg_roles b ON b.oid=m.roleid JOIN pg_roles g ON g.oid=m.grantor),
 'effective_memberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('member',r.rolname,'target',t.rolname,'member_of',pg_has_role(r.oid,t.oid,'MEMBER'),'usable',pg_has_role(r.oid,t.oid,'USAGE'),'settable',pg_has_role(r.oid,t.oid,'SET'))),'[]') FROM roles r CROSS JOIN pg_roles t WHERE r.oid<>t.oid AND pg_has_role(r.oid,t.oid,'MEMBER')),
 'database_acl',(SELECT jsonb_build_object('owner',pg_get_userbyid(datdba),'acl',datacl::text) FROM pg_database WHERE datname=current_database()),
 'schema_acl',(SELECT jsonb_agg(jsonb_build_object('schema',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text)) FROM pg_namespace WHERE nspname NOT LIKE 'pg_%' AND nspname<>'information_schema'),
 'effective_schema',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'schema',n.nspname,'usage',has_schema_privilege(r.oid,n.oid,'USAGE'),'create',has_schema_privilege(r.oid,n.oid,'CREATE'))) FROM roles r CROSS JOIN pg_namespace n WHERE n.nspname IN ('public','founder_governance')),
 'effective_database',(SELECT jsonb_agg(jsonb_build_object('role',rolname,'connect',has_database_privilege(oid,current_database(),'CONNECT'),'create',has_database_privilege(oid,current_database(),'CREATE'),'temp',has_database_privilege(oid,current_database(),'TEMP'))) FROM roles),
 'relations',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'forced_rls',c.relforcerowsecurity)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='founder_governance'),
 'column_acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'acl',a.attacl::text)),'[]') FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='founder_governance' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL),
 'sequences',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text)),'[]') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='S' AND n.nspname NOT LIKE 'pg_%'),
 'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text,'control_execute',has_function_privilege('leqvor_governance_control',p.oid,'EXECUTE'),'executor_execute',has_function_privilege('leqvor_governance_executor',p.oid,'EXECUTE'),'auditor_execute',has_function_privilege('leqvor_governance_auditor',p.oid,'EXECUTE'))),'[]') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_toast%'),
 'default_acls',(SELECT coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',coalesce(n.nspname,'GLOBAL'),'type',d.defaclobjtype,'acl',d.defaclacl::text)),'[]') FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid))) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='founder_governance' AND NOT t.tgisinternal),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',con.conname,'definition',pg_get_constraintdef(con.oid),'validated',con.convalidated)) FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='founder_governance'),
 'settings',(SELECT coalesce(jsonb_agg(jsonb_build_object('role',pg_get_userbyid(setrole),'db',setdatabase,'settings',setconfig)),'[]') FROM pg_db_role_setting WHERE setrole IN (SELECT oid FROM roles)),
 'rows',jsonb_build_object('root_state',(SELECT count(*) FROM founder_governance.root_state),'audit_events',(SELECT count(*) FROM founder_governance.audit_events),'execution_events',(SELECT count(*) FROM founder_governance.execution_events),'execution_reservations',(SELECT count(*) FROM founder_governance.execution_reservations)),
 'customer_schemas',(SELECT count(*) FROM pg_namespace WHERE nspname IN ('auth','storage','supabase_functions'))
) AS governance_privilege_audit;
COMMIT;
